<script setup>
import{computed,nextTick,onBeforeUnmount,onMounted,ref,shallowRef}from'vue';
import{createStore,defaultReminder,fromDraft,localDate,moveBefore,newDraft,repeatLabel,toDraft,validateSettings}from'./todo-model.js';
import sound from'./original/ding-B9BOXEwg.mp3';
import TodoIcon from'./TodoIcon.vue';
const props=defineProps({host:Object,initialSettings:Object,initialSnapshot:Object,calendarMode:Boolean,calendarReady:Function});
const settings=ref(validateSettings(props.initialSettings)),snapshot=shallowRef(props.initialSnapshot),draft=ref({}),themeDraft=ref({}),showHistory=ref(false),editor=ref(),confirm=ref(),themeDialog=ref(),completionSound=ref(),saving=ref(false),themeSaving=ref(false),error=ref(''),editError=ref(''),themeError=ref(''),audioError=ref(''),uncertain=ref(false),pendingDelete=ref(''),dragged=ref('');
const editRevision=ref(props.initialSnapshot.revision),deleteRevision=ref(props.initialSnapshot.revision);
let alive=true,timer,polling=false;
const store=createStore(props.initialSnapshot,(method,args)=>props.host.request(method,args),{preview:props.host.preview,changed:value=>{snapshot.value=value;}});
async function beforeLibrarySwitch(){await store.flush();if(saving.value||uncertain.value||store.hasPending())throw Error('上次操作结果未确定或仍在保存，请先重试');if(themeSaving.value||[editor,confirm,themeDialog].some(dialog=>dialog.value?.open))throw Error('请先保存或关闭编辑/设置窗口，再切换数据源');return true;}
props.host.beforeLibrarySwitch=beforeLibrarySwitch;
const items=computed(()=>snapshot.value.todos.filter(t=>!!t.completedDateTime===showHistory.value));
const calendarReminder=computed(()=>{if(!props.calendarMode)return null;const reminders=snapshot.value.reminders.filter(r=>['failed','unknown','expired'].includes(r.delivery));if(!reminders.length)return null;return{todoId:reminders[0].todoId,text:reminderStatus({id:reminders[0].todoId}),total:reminders.length};});
const theme=computed(()=>({'--widget-background-color':settings.value.background,'--widget-color':settings.value.foreground,'--widget-divider-color':settings.value.divider,'--widget-border-radius':settings.value.radius+'px'}));
function canChange(){if(props.host.preview)return false;if(store.hasPending()){error.value='上次操作结果未确定，请先重试';uncertain.value=true;return false;}return true;}
function openNew(date){if(!canChange())return;editRevision.value=snapshot.value.revision;draft.value=newDraft();if(typeof date==='string')draft.value.dueDate=date;editError.value='';editor.value.showModal();}
function openEdit(id){if(!canChange())return;const todo=snapshot.value.todos.find(t=>t.id===id&&!t.completedDateTime);if(!todo)return;editRevision.value=snapshot.value.revision;draft.value=toDraft(todo);editError.value='';editor.value.showModal();}
function setRepeat(value){draft.value.recurrence=value;if(value&&!draft.value.dueDate)draft.value.dueDate=localDate(Date.now());}
function setReminder(enabled){draft.value.isReminderOn=enabled;if(enabled&&!draft.value.reminder)draft.value.reminder=defaultReminder(Date.now());}
function failed(reason,prefix){uncertain.value=store.hasPending();return prefix+String(reason?.message||reason);}
async function saveTodo(){if(props.host.preview||saving.value)return;saving.value=true;editError.value='';try{const previous=snapshot.value.todos.find(t=>t.id===draft.value.id),todo=fromDraft(draft.value,previous,Date.now());await store.change('save',{todo,expectedRevision:editRevision.value});if(alive){uncertain.value=false;editor.value.close();}}catch(reason){if(alive)editError.value=failed(reason,'待办未保存：');}finally{saving.value=false;}}
function playCompletion(){audioError.value='';try{const audio=completionSound.value;if(!audio)throw Error('音效未加载');audio.currentTime=0;Promise.resolve(audio.play()).catch(()=>{if(alive)audioError.value='待办已完成，提示音未播放。';});}catch{if(alive)audioError.value='待办已完成，提示音未播放。';}}
async function toggleComplete(todo,{silent=false}={}){if(!canChange()||saving.value)return;saving.value=true;error.value='';try{const completing=!todo.completedDateTime;await store.change(completing?'complete':'reopen',{id:todo.id});if(alive){uncertain.value=false;if(completing&&!silent)playCompletion();}}catch(reason){if(alive)error.value=failed(reason,'待办未更新：');}finally{saving.value=false;}}
function completionChanged(event,todo){event.target.checked=!!todo.completedDateTime;return toggleComplete(todo);}
function askDelete(id){if(!canChange())return;deleteRevision.value=snapshot.value.revision;pendingDelete.value=id;error.value='';confirm.value.showModal();}
async function remove(){if(props.host.preview||saving.value)return;saving.value=true;error.value='';try{await store.change('delete',{id:pendingDelete.value,expectedRevision:deleteRevision.value});if(alive){uncertain.value=false;confirm.value.close();editor.value?.close();}}catch(reason){if(alive)error.value=failed(reason,'删除未保存：');}finally{saving.value=false;}}
async function dropBefore(from,to){if(!canChange()||saving.value||showHistory.value)return;error.value='';saving.value=true;try{await store.change('reorder',{ids:moveBefore(snapshot.value,from,to)});}catch(reason){if(alive)error.value=failed(reason,'排序未保存：');}finally{dragged.value='';saving.value=false;}}
function dragStart(event,id){if(event.button!==0||!canChange()||showHistory.value)return;dragged.value=id;event.currentTarget.setPointerCapture(event.pointerId);}
function dragEnd(event){const from=dragged.value;dragged.value='';if(!from)return;const target=window.document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-todo-id]');if(!target||target.dataset.todoId===from)return;const bounds=target.getBoundingClientRect(),index=items.value.findIndex(t=>t.id===target.dataset.todoId),to=event.clientY<bounds.top+bounds.height/2?target.dataset.todoId:items.value[index+1]?.id||'';void dropBefore(from,to);}
async function retryOperation(){if(saving.value)return;saving.value=true;try{await store.retry();if(alive){uncertain.value=false;error.value='';editError.value='';editor.value?.close();confirm.value?.close();}}catch(reason){if(alive)error.value=failed(reason,'重试未完成：');}finally{saving.value=false;}}
async function refresh(){if(props.host.preview||polling||saving.value||store.hasPending()||!alive||[editor,confirm,themeDialog].some(dialog=>dialog.value?.open))return;polling=true;try{await store.refresh();if(alive)error.value='';}catch(reason){if(alive)error.value='待办刷新失败：'+String(reason?.message||reason);}finally{polling=false;}}
function openTheme(){themeDraft.value={...settings.value};themeError.value='';themeDialog.value.showModal();}
async function saveTheme(){if(props.host.preview||themeSaving.value)return;themeSaving.value=true;themeError.value='';try{const value=validateSettings(themeDraft.value);for(const key of ['background','foreground','divider'])if(!CSS.supports('color',value[key]))throw Error('颜色无效');const saved=validateSettings(await props.host.request('settings.update',value));if(alive){settings.value=saved;themeDialog.value.close();}}catch(reason){if(alive)themeError.value='设置未保存：'+String(reason?.message||reason);}finally{themeSaving.value=false;}}
function reminderStatus(todo){const value=snapshot.value.reminders.find(r=>r.todoId===todo.id);if(!value)return'';if(value.delivery==='failed')return'提醒未递送：'+(value.error||'系统未接受');if(value.delivery==='unknown')return'上次提醒递送结果未确定';if(value.delivery==='expired')return'提醒已过期';return'';}
function dispose(){alive=false;clearInterval(timer);store.dispose();if(props.host.beforeLibrarySwitch===beforeLibrarySwitch)props.host.beforeLibrarySwitch=undefined;}
onBeforeUnmount(dispose);onMounted(async()=>{await props.host.ready();if(!alive||props.host.preview)return;if(props.calendarMode){if(props.calendarReady)await props.calendarReady({snapshot,settings,draft,themeDraft,editor,themeDialog,editError,saving,openNew,openEdit,saveTodo,askDelete,remove,openTheme,saveTheme});}else if(new URLSearchParams(location.search).get('verify')==='widgetjs')await verifySession();if(alive)timer=setInterval(()=>void refresh(),1500);});
async function verifySession(){
 const storage=await props.host.request('storage.get'),prior=storage.verification,label='待办'+props.host.instanceId.slice(0,8),background='#'+props.host.instanceId.replaceAll('-','').slice(0,6);let invalidSaveRejected=prior?.invalidSaveRejected===true,actionsVerified=prior?.actionsVerified===true,checkboxRollbackVerified=prior?.checkboxRollbackVerified===true;
 if(!prior?.uiVerified){
  openNew();await nextTick();draft.value.title='';const before=JSON.stringify((await props.host.request('todo.get')).todos);await saveTodo();invalidSaveRejected=before===JSON.stringify((await props.host.request('todo.get')).todos)&&editError.value.includes('未保存');
  draft.value.title=label;draft.value.dueDate=localDate(Date.now()+86400000);setRepeat('RRULE:FREQ=DAILY');await nextTick();window.document.getElementById('todo-form').requestSubmit();for(let n=0;n<100&&saving.value;n++)await new Promise(resolve=>setTimeout(resolve,50));if(saving.value||editor.value.open)throw Error('待办表单未完成：'+editError.value);
  const original=snapshot.value.todos.find(t=>t.title===label);await props.host.request('todo.change',{requestId:crypto.randomUUID(),expectedRevision:snapshot.value.revision,operation:'save',todo:{...original}});await nextTick();const checkbox=window.document.querySelector('.completion');checkbox.checked=true;checkbox.dispatchEvent(new Event('change',{bubbles:true}));for(let n=0;n<100&&saving.value;n++)await new Promise(resolve=>setTimeout(resolve,50));await nextTick();checkboxRollbackVerified=!saving.value&&!checkbox.checked&&!snapshot.value.todos.find(t=>t.id===original.id)?.completedDateTime&&error.value.includes('未更新');await toggleComplete(snapshot.value.todos.find(t=>t.id===original.id),{silent:true});showHistory.value=true;await nextTick();const completed=!!snapshot.value.todos.find(t=>t.id===original.id)?.completedDateTime&&window.document.querySelector('.todo-item.completed')!==null;
  await toggleComplete(snapshot.value.todos.find(t=>t.id===original.id),{silent:true});showHistory.value=false;
  const generated=snapshot.value.todos.find(t=>t.title===label&&t.id!==original.id);const repeated=!!generated&&Date.parse(generated.dueDateTime)>Date.parse(original.dueDateTime);if(generated){askDelete(generated.id);await remove();}
  openNew();draft.value.title='验收临时排序';await saveTodo();const extra=snapshot.value.todos.find(t=>t.title==='验收临时排序');await dropBefore(extra.id,original.id);const sorted=snapshot.value.todos[0].id===extra.id;askDelete(extra.id);await remove();
  actionsVerified=checkboxRollbackVerified&&completed&&repeated&&sorted&&snapshot.value.todos.length===1&&!snapshot.value.todos[0].completedDateTime;
  openTheme();themeDraft.value.title=label;themeDraft.value.background=background;themeDraft.value.radius=12;await saveTheme();
 }
 await nextTick();const audio=completionSound.value;if(audio.readyState<1)await new Promise(resolve=>{audio.addEventListener('loadedmetadata',resolve,{once:true});audio.addEventListener('error',resolve,{once:true});setTimeout(resolve,3500);});
 const saved=await props.host.request('settings.get'),stored=await props.host.request('todo.get'),configurationSaved=stored.todos.some(t=>t.title===label&&!t.completedDateTime)&&saved.background===background&&saved.title===label,imagesLoaded=audio.readyState>=1&&audio.duration>0,stylesLoaded=getComputedStyle(window.document.querySelector('.todo-list-widget')).borderRadius==='12px'&&getComputedStyle(window.document.querySelector('.todo-list-widget .header')).borderBottomStyle==='solid';
 await props.host.request('storage.set',{...storage,verification:{uiVerified:configurationSaved&&invalidSaveRejected&&actionsVerified&&imagesLoaded&&stylesLoaded,configurationSaved,invalidSaveRejected,actionsVerified,checkboxRollbackVerified,imagesLoaded,audioMetadataLoaded:imagesLoaded,audiblePlaybackVerified:false,stylesLoaded,savedLabel:label,runtimeLoads:(prior?.runtimeLoads??0)+1,localOnly:true,todoRevision:stored.revision,todoIds:stored.todos.map(t=>t.id),renderedText:window.document.querySelector('.list-body').textContent.slice(0,500),origin:location.origin}});
}
</script>
<template><main class="widget" :style="theme"><section v-if="!calendarMode" class="todo-list-widget"><header class="header"><div class="title">{{showHistory?'已完成':settings.title}}</div><nav class="actions" aria-label="待办操作"><button v-if="showHistory" type="button" aria-label="返回待办" title="返回待办" @click="showHistory=false"><TodoIcon name="circle-chevron-left"/></button><button v-else type="button" aria-label="已完成历史" title="已完成历史" @click="showHistory=true"><TodoIcon name="rotate-ccw-clock"/></button><button type="button" aria-label="添加待办" title="添加待办" :disabled="host.preview||saving||uncertain" @click="openNew()"><TodoIcon name="plus"/></button><button type="button" aria-label="待办设置" title="待办设置" @click="openTheme">⚙</button></nav></header><div class="list-body"><div class="scroll-wrapper"><div class="list"><div v-for="todo in items" :key="todo.id" class="draggable" :data-todo-id="todo.id"><div class="todo-item" :class="{completed:!!todo.completedDateTime}"><button v-if="!showHistory" class="drag-handle" type="button" aria-label="拖动排序" :disabled="host.preview||saving||uncertain" @pointerdown="dragStart($event,todo.id)" @pointerup="dragEnd" @pointercancel="dragged=''">⠿</button><input class="completion" type="checkbox" :aria-label="(todo.completedDateTime?'恢复待办 ':'完成待办 ')+todo.title" :checked="!!todo.completedDateTime" :disabled="host.preview||saving||uncertain" @change="completionChanged($event,todo)"><div class="todo"><p>{{todo.title}}</p><div v-if="todo.dueDateTime||todo.recurrence" class="details"><span v-if="todo.dueDateTime"><TodoIcon name="clock" :size="12"/> {{localDate(todo.dueDateTime)}}</span><span v-if="todo.recurrence"><TodoIcon name="repeat" :size="12"/> {{repeatLabel(todo.recurrence)}}</span></div><span v-if="reminderStatus(todo)" class="reminder-error">{{reminderStatus(todo)}}</span></div><div class="actions"><button v-if="!showHistory" class="icon edit" type="button" :aria-label="'编辑待办 '+todo.title" :disabled="host.preview||saving||uncertain" @click.stop="openEdit(todo.id)"><TodoIcon name="pencil"/></button><button class="icon delete" type="button" :aria-label="'删除待办 '+todo.title" :disabled="host.preview||saving||uncertain" @click.stop="askDelete(todo.id)"><TodoIcon name="trash"/></button></div></div></div><button v-if="!items.length&&!showHistory" class="empty" type="button" :disabled="host.preview||uncertain" @click="openNew()">添加待办</button><p v-else-if="!items.length" class="empty">暂无已完成事项</p></div></div></div></section><section v-else class="calendar-content"><slot :snapshot="snapshot" :settings="settings" :open-new="openNew" :open-edit="openEdit"/><button class="calendar-configure" type="button" aria-label="大号日历设置" @click="openTheme">⚙</button></section><audio ref="completionSound" :src="sound" preload="metadata"></audio><output class="status" role="status">{{host.preview?'预览 · 不保存':error}}<span v-if="!host.preview&&calendarReminder" class="reminder-state">{{calendarReminder.total}}项提醒需要处理：{{calendarReminder.text}}<button type="button" @click="openEdit(calendarReminder.todoId)">查看日程</button></span><template v-if="uncertain"> 上次操作结果未确定。<button type="button" :disabled="saving" @click="retryOperation">重试</button></template><template v-if="audioError">{{audioError}}<button type="button" @click="playCompletion">重试提示音</button></template></output>
<dialog ref="editor" @cancel="saving&&$event.preventDefault()"><form id="todo-form" class="todo-editor" @submit.prevent="saveTodo"><h2>{{snapshot.todos.some(t=>t.id===draft.id)?'编辑':'添加'}}待办</h2><fieldset class="editor-fields" :disabled="saving||uncertain"><label>内容<input v-model="draft.title" maxlength="4096" required placeholder="请输入待办内容"></label><label>到期日期<div class="date-input"><input v-model="draft.dueDate" type="date"><button v-if="draft.dueDate" type="button" aria-label="清除到期日期" @click="draft.dueDate=''">×</button></div></label><label>重复<select :value="draft.recurrence" @change="setRepeat($event.target.value)"><option value="">不重复</option><option value="RRULE:FREQ=DAILY">每天重复</option><option value="RRULE:FREQ=WEEKLY">每周重复</option><option value="RRULE:FREQ=MONTHLY">每月重复</option><option v-if="draft.recurrence==='RRULE:FREQ=YEARLY'" value="RRULE:FREQ=YEARLY">每年重复</option></select></label><label>提醒<input class="switch" type="checkbox" :checked="draft.isReminderOn" @change="setReminder($event.target.checked)"></label><label v-if="draft.isReminderOn">提醒时间<input v-model="draft.reminder" type="datetime-local" required></label></fieldset><p v-if="reminderStatus(draft)" class="error" role="status">{{reminderStatus(draft)}}</p><p class="error" role="status">{{editError}}</p><p v-if="uncertain" class="error">上次操作结果未确定，请重试原操作。</p><footer><button v-if="snapshot.todos.some(t=>t.id===draft.id)" type="button" :disabled="saving||uncertain" @click="askDelete(draft.id)">删除</button><button type="button" :disabled="saving" @click="editor.close()">取消</button><button v-if="uncertain" type="button" :disabled="saving" @click="retryOperation">重试</button><button v-else type="submit" :disabled="saving||host.preview">{{saving?'保存中':'保存'}}</button></footer></form></dialog>
<dialog ref="confirm" @cancel="saving&&$event.preventDefault()"><h2>删除待办？</h2><p>此操作会删除当前数据源中的事项和对应提醒；若已连接共享库，全部连接实例都会受影响。</p><p class="error">{{error}}</p><footer><button type="button" :disabled="saving" @click="confirm.close()">取消</button><button v-if="uncertain" type="button" :disabled="saving" @click="retryOperation">重试</button><button v-else type="button" :disabled="saving||host.preview" @click="remove">确认删除</button></footer></dialog>
<dialog ref="themeDialog" @cancel="themeSaving&&$event.preventDefault()"><form @submit.prevent="saveTheme"><h2>{{calendarMode?'大号日历设置':'待办设置'}}</h2><label v-if="calendarMode">一周开始日<select v-model.number="themeDraft.firstDayOfWeek"><option :value="0">周日</option><option :value="1">周一</option></select></label><label v-if="!calendarMode">组件标题<input v-model="themeDraft.title" maxlength="120"></label><label>背景颜色<input v-model="themeDraft.background" maxlength="80" required></label><label>文字颜色<input v-model="themeDraft.foreground" maxlength="80" required></label><label v-if="!calendarMode">分隔线颜色<input v-model="themeDraft.divider" maxlength="80" required></label><label>圆角<input v-model.number="themeDraft.radius" type="number" min="0" max="50" required></label><p class="error" role="status">{{themeError}}</p><footer><button type="button" :disabled="themeSaving" @click="themeDialog.close()">取消</button><button type="submit" :disabled="themeSaving||host.preview">{{themeSaving?'保存中':'保存'}}</button></footer></form></dialog></main></template>
